package plates

/** The camelCase name an enum constant has in the shared data, vectors and SVG attributes: `BORDER_WIDTH` is `borderWidth`. */
internal val Enum<*>.wireName: String
    get() = name.lowercase().replace(Regex("_(.)")) { it.groupValues[1].uppercase() }

internal inline fun <reified T : Enum<T>> wireValueOf(name: String): T = enumValues<T>().first { it.wireName == name }
